package org.eclipse.rdf4j.common.app;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.InputStream;
import java.util.Properties;

import org.junit.jupiter.api.Test;

class WorkbenchDefaultSecurityPropertiesTest {

	@Test
	void jsonpIsDisabledForPublicWorkbenchByDefault() throws Exception {
		Properties defaults = new Properties();
		try (InputStream input = AppConfiguration.class.getResourceAsStream(
				"/org/eclipse/rdf4j/common/app/config/defaults/application.properties")) {
			assertThat(input).isNotNull();
			defaults.load(input);
		}
		assertThat(defaults.getProperty("org.eclipse.rdf4j.workbench.jsonp.enabled")).isEqualTo("false");
	}
}
